#include <stdio.h>
#include <string.h>

int main(void) {
    char msg[300];
    if (fgets(msg, sizeof(msg), stdin) == NULL) return 0;

    int divertidos = 0, chateados = 0;
    size_t n = strlen(msg);

    for (size_t i = 0; i + 2 < n; i++) {
        if (msg[i] == ':' && msg[i + 1] == '-') {
            if (msg[i + 2] == ')') {
                divertidos++;
            } else if (msg[i + 2] == '(') {
                chateados++;
            }
        }
    }

    if (divertidos > chateados) {
        puts("divertido");
    } else if (chateados > divertidos) {
        puts("chateado");
    } else {
        puts("neutro");
    }

    return 0;
}
